+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { createInventory, ingreso } from "../domain/inventory.ts";
+import { createLayout } from "../domain/layout.ts";
+import { buildThesisSeed2026, type Scenario } from "../scenarios/thesis-seed-2026.ts";
