+
+function scenarioWithEmptyBins(): Scenario {
+  const layout = createLayout(
+    [{ id: "zone-a", name: "Zone A" }],
+    [
+      { id: "bin-1", zoneId: "zone-a", code: "A-01" },
+      { id: "bin-2", zoneId: "zone-a", code: "A-02" },
+      { id: "bin-3", zoneId: "zone-a", code: "A-03" },
+    ],
+  );
+
+  let inventory = createInventory(layout.bins.map((bin) => bin.id));
+  inventory = ingreso(inventory, "bin-1", "sku-a", 2);
+  inventory = ingreso(inventory, "bin-1", "sku-b", 5);
