+import type { WarehouseProjection } from "./contracts.ts";
+import { getQuantity } from "../domain/inventory.ts";
+
+export type SkuBinSpread = Readonly<Record<string, number>>;
+
+export const skuBinSpreadProjection: WarehouseProjection<SkuBinSpread> = {
+  id: "sku-bin-spread",
+  project(scenario) {
+    const spread: Record<string, number> = {};
+
+    for (const skuId of scenario.skus) {
+      let binsWithSku = 0;
+      for (const bin of scenario.layout.bins) {
+        if (getQuantity(scenario.inventory, bin.id, skuId) > 0) {
+          binsWithSku += 1;
+        }
+      }
+      spread[skuId] = binsWithSku;
+    }
+
+    return spread;
+  },
+};
