+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { createInventory, ingreso } from "../domain/inventory.ts";
+import { createLayout } from "../domain/layout.ts";
+import { buildThesisSeed2026, type Scenario } from "../scenarios/thesis-seed-2026.ts";
+import { zoneUnitTotalsProjection } from "./projection-01.ts";
+
+function scenarioWithStock(): Scenario {
+  const layout = createLayout(
+    [
+      { id: "zone-a", name: "Zone A" },
+      { id: "zone-b", name: "Zone B" },
+    ],
+    [
+      { id: "bin-a-1", zoneId: "zone-a", code: "A-01" },
+      { id: "bin-a-2", zoneId: "zone-a", code: "A-02" },
+      { id: "bin-b-1", zoneId: "zone-b", code: "B-01" },
+    ],
+  );
+
+  let inventory = createInventory(layout.bins.map((bin) => bin.id));
+  inventory = ingreso(inventory, "bin-a-1", "sku-a", 5);
+  inventory = ingreso(inventory, "bin-a-2", "sku-b", 7);
+  inventory = ingreso(inventory, "bin-b-1", "sku-a", 11);
+
+  return { name: "sample", layout, inventory, skus: ["sku-a", "sku-b"] };
+}
+
+test("zone-unit-totals sums stock by zone from the provided scenario", () => {
+  assert.deepEqual(zoneUnitTotalsProjection.project(scenarioWithStock()), {
+    "zone-a": 12,
+    "zone-b": 11,
+  });
+});
