+test("zone-unit-totals answers the thesis seed scenario without hardcoded constants", () => {
+  assert.deepEqual(zoneUnitTotalsProjection.project(buildThesisSeed2026()), {
+    "zone-1": 35,
+    "zone-2": 40,
+    "zone-3": 65,
+    "zone-4": 30,
+  });
+});
