@@ -0,0 +1,40 @@
+import { pathToFileURL } from "node:url";
+import { getScenario, THESIS_SEED_2026 } from "../scenarios/thesis-seed-2026.ts";
+import { getWarehouseProjections } from "./registry.ts";
+
+const SCHEMA_VERSION = 1;
+
+export interface StudyWideGraphReport {
+  readonly schemaVersion: number;
+  readonly moduleCount: number;
+  readonly scenario: string;
+  readonly projections: readonly {
+    readonly projectionId: string;
+    readonly value: unknown;
+  }[];
+}
+
+export function buildStudyWideGraphReport(): StudyWideGraphReport {
+  const scenario = getScenario(THESIS_SEED_2026);
+  const projections = getWarehouseProjections();
+
+  return {
+    schemaVersion: SCHEMA_VERSION,
+    moduleCount: projections.length,
+    scenario: scenario.name,
+    projections: projections.map((projection) => ({
+      projectionId: projection.id,
+      value: projection.project(scenario),
+    })),
+  };
+}
+
+export function main(): string {
+  return JSON.stringify(buildStudyWideGraphReport());
+}
+
+const isMainModule = process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
+
+if (isMainModule) {
+  process.stdout.write(main());
+}

