+import type { WarehouseProjection } from "./contracts.ts";
+import { getQuantity } from "../domain/inventory.ts";
+
+export type ZoneUnitTotals = Readonly<Record<string, number>>;
+
+export const projection: WarehouseProjection<ZoneUnitTotals> = {
+  id: "zone-unit-totals",
+  project(scenario) {
+    const totals: Record<string, number> = {};
+    for (const zone of scenario.layout.zones) {
+      totals[zone.id] = 0;
+    }
+
+    for (const bin of scenario.layout.bins) {
+      for (const skuId of scenario.skus) {
+        totals[bin.zoneId] = (totals[bin.zoneId] ?? 0) + getQuantity(scenario.inventory, bin.id, skuId);
+      }
+    }
+
+    return totals;
+  },
+};
+
+export const zoneUnitTotalsProjection = projection;
