+import type { WarehouseProjection } from "./contracts.ts";
+import { getQuantity } from "../domain/inventory.ts";
+
+export interface BinOccupancy {
+  readonly stockedBins: number;
+  readonly emptyBins: number;
+  readonly totalBins: number;
+}
+
+export const projection: WarehouseProjection<BinOccupancy> = {
+  id: "bin-occupancy",
+  project(scenario) {
+    let stockedBins = 0;
+
+    for (const bin of scenario.layout.bins) {
+      const hasStock = scenario.skus.some((skuId) => getQuantity(scenario.inventory, bin.id, skuId) > 0);
+      if (hasStock) {
+        stockedBins += 1;
+      }
+    }
+
+    const totalBins = scenario.layout.bins.length;
+    return {
+      stockedBins,
+      emptyBins: totalBins - stockedBins,
+      totalBins,
+    };
+  },
+};
+
+export const binOccupancyProjection = projection;
