+  const layout = createLayout(
+    [
+      { id: "zone-a", name: "Zone A" },
+      { id: "zone-b", name: "Zone B" },
+    ],
+    [
+      { id: "bin-a-1", zoneId: "zone-a", code: "A-01" },
